		new FastNTriplesParser(RDFFormat.NQUADS, () -> false).parse(new ByteArrayInputStream(bytes),
				(subject, predicate, object, context) -> streamed.add(describe(subject, predicate, object, context)));
		java.util.List<String> blocked = new java.util.ArrayList<>();
		long statements = new FastNTriplesParser(RDFFormat.NQUADS, () -> false).parseBlock(bytes, 0, bytes.length, 1L,
				(subject, predicate, object, context) -> blocked.add(describe(subject, predicate, object, context)));

		assertEquals(4L, statements);
		assertEquals(streamed, blocked);
